def haɗa_zuwa_bayanan():
    # Taimakar bayanan
    bayanan = []

    # Masu zuwa
    while True:
        masu_zuwa = input("Kasa zuwa bayanan (ta kara 'sirri' don ya kara): ")
        if masu_zuwa.lower() == 'sirri':
            break
        bayanan.append(masu_zuwa)

    # Tambaya don bincika idan sunan mai amfani ya wanzu a cikin bayanan
    if bayanan:
        sunan_mai_amfani = input("Kasa sunan mai amfani: ")
        if sunan_mai_amfani in bayanan:
            print("Ta dawo karya")
        else:
            print("Ba ta dawo karya")
    else:
        print("Bayanan bai kara")

# Tsoro
haɗa_zuwa_bayanan()
